import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"36、【明夷】 離下坤上","description":"周易口訣義 - 36、【明夷】 離下坤上","frontmatter":{"title":"36、【明夷】 離下坤上","description":"周易口訣義 - 36、【明夷】 離下坤上"},"headers":[],"relativePath":"classics/koujueyi/038.md","filePath":"classics/koujueyi/038.md"}'),r={name:"classics/koujueyi/038.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_36、【明夷】-離下坤上" tabindex="-1">36、【明夷】 離下坤上 <a class="header-anchor" href="#_36、【明夷】-離下坤上" aria-label="Permalink to “36、【明夷】 離下坤上”">​</a></h1><p>彖曰：明入地中，「明夷」。內文明而外柔順，以蒙大難，文王以之。「利艱貞」，晦其明也。內難而能正其志，箕子以之。象曰：明入地中，「明夷」。君子以蒞眾，用晦而明。</p><p>初九：明夷于飛，垂其翼。君子於行，三日不食。有攸往，主人有言。</p><p>象曰：「君子於行」，義不食也。</p><p>六二：明夷，夷於左股，用拯馬壯，吉。</p><p>象曰：六二之吉，順以則也。</p><p>九三，明夷於南狩，得其大首，不可疾貞。</p><p>象曰：南狩之志，乃大得也。</p><p>六四，入於左腹，獲明夷之心，於出門庭。</p><p>象曰：「入於左腹」，獲心意也。</p><p>六五，箕子之明夷，利貞。</p><p>象曰：箕子之貞，明不可息也。</p><p>上六，不明晦，初登於天，後入於地。</p><p>象曰：「初登於天」，照四國也；「後入於地」，失則也。</p><p>解讀</p><p>「明夷，利艱貞」者，夷，傷也，離為日，喻日入地中，傷明之象，故曰「明夷」。以人事明之，亦猶君在上，臣不敢顯其明德，必須艱固為貞，又不可隨世傾邪，故曰「利艱貞」也。象曰「明入地中，明夷」者，夫日之為道，即合升高照耀，今在地中，傷其光耀之象。「君子以蒞眾，用晦而明」者，蒞，臨也，晦，暗也。故君子當是時以臨於眾，內懷明德，外彰晦暗，無為無事，清淨不欺，閉智塞耀，故老子云「我無為而人自化」是也。</p><p>「初九，明夷于飛，垂其翼，君子於行，三日不食。有攸往，主人有言」者，上六以陰居上，是暗君之象。初九既居無位之地，未食暗君之祿，可以逃避危難，不由軌路，如鳥之飛，故曰「于飛」；懷懼而行，以求隱翳，故曰「垂其翼」；雖處危懼，志存道義，故曰「於行」；切於逃難，飢不暇食，故曰「三日不食」；處危懼之時，與眾乖異，故主人有相疑之言，故曰「有攸往，主人有言」也。</p><p>「六二，明夷，夷於左股，用拯馬壯吉」者，左者，明所傷小也。左股被傷，猶得順而處位。六二以柔居中，不為剛猛之事，即不為暗主所疑，猶處其位，然後時進退，乃得隨時，用拯馬而避之，得吉也。</p><p>「九三，明夷於南狩，得其大首，不可疾貞」者，南是陽明之方也；狩者，征伐之義。九三以離明之極，而以征伐至暗之主，乃獲暗君之頭首，故曰「南狩，得其大首」也。既誅暗主，將正其民，民迷日久，即可化之以漸，不可速使從正，故曰「不可疾貞」也。</p><p>「六四：入子左腹，獲明夷之心，於出門庭」者，左者，取其順也；腹者，獲其心。既知君意，雖近不危，縱使逃難，不遠適，止於門庭而已也。</p><p>「六五箕子之明夷，利貞」者，最近暗君，猶箕子之近殷紂，執正不回而不能滅，利以正貞，故小象雲「明不可息」也。息，滅也。</p><p>上六：不明晦，初登於天，後入於地者，處明夷之極，是暗晦之主，殷紂當之也。「初登於位」，本謂光德顯於四方，及其無道，果致被伐，至於喪滅，故曰「後入於地」也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
